const SAMPLE_FILES = [
  { name: "Q3-board-report.pdf", size: 1_258_291, type: "application/pdf", uri: "sample://q3-board-report.pdf" },
  { name: "team-offsite.png", size: 846_120, type: "image/png", uri: "sample://team-offsite.png" },
